import sys

def main() -> None:
    data = sys.stdin.read().split()
    n = int(data[0]); w = int(data[1]); t = int(data[2])
    h = [int(x) for x in data[3:3 + n]]
    ans = 0
    for l in range(n):
        total = 0
        tallest = 0
        for r in range(l, n):
            total += h[r]
            if total > w:
                break
            if h[r] > tallest:
                tallest = h[r]
            if tallest >= t:
                ans += 1
    print(ans)

main()
